def add(key,u,r,start,solve,verify,pit,summary):D[key]=(u,r,start,solve,verify,pit,summary)
add('ch01-q01','원래 a와 b의 값을 서로 바꿔요. 한 값을 덮어쓰기 전에 보관할 곳이 필요해요.','“서로 교환”은 swap이에요. 대입은 오른쪽 값을 읽어 왼쪽 저장소를 바꾸므로, 임시 변수 temporary variable로 옛 a를 보존해야 해요.',code('temp ← a'),code('temp ← a\na ← b\nb ← temp'),'a=3,b=8에서 temp=3 → a=8,b=8 → a=8,b=3이에요. 임의의 옛 값 A,B도 최종 a=B,b=A이므로 두 조건을 만족해요.','a←b 다음 b←a를 쓰면 원래 a가 이미 사라져 두 값이 같아져요.','임시 보관 → a에 b → b에 옛 a')
add('ch01-q02','두 정수를 읽어 큰 쪽을 내보내요. 같은 값이면 어느 쪽을 골라도 같은 최댓값이에요.','“더 큰 수”는 comparison과 selection의 단서예요. a≥b와 a&lt;b는 가능한 입력을 겹치지 않게 전부 나눠요.',code('read a, b'),code('read a, b\nif a >= b then output a\nelse output b'),'3,8→8; 8,3→8; -2,-7→-2; 4,4→4예요. 두 분기에서 출력이 두 입력 이상이며 실제 입력 중 하나이므로 max의 정의를 만족해요.','초기 최대값을 0으로 두면 음수 두 개에서 잘못된 답이 나와요.','입력 두 개를 비교해 큰 값 선택')
add('ch01-q03','1부터 양의 정수 n까지 빠짐없이 더하는 알고리즘이에요.','“1부터 n까지”는 누적 합 accumulator의 단서예요. 합의 항등원은 0이고 각 반복에서 현재 i를 정확히 한 번 더해요.',code('sum ← 0'),code('sum ← 0\nfor i ← 1 to n\n    sum ← sum + i\noutput sum'),'n=4에서 sum은 0→1→3→6→10이에요. i까지 끝났을 때 sum=1+…+i라는 불변식이 초기·유지·종료를 만족해요. 별도 공식 n(n+1)/2도 10을 주어요.','i&lt;n으로 반복하면 n을 빼먹어요. C로 옮길 때는 합이 정수 타입 범위 안에 있어야 해요.','0에서 시작해 1..n 누적')
add('ch05-q01','A부터 E까지 차례로 큐에 넣고 모두 꺼내요.','“큐(queue)”는 먼저 온 것이 먼저 나가는 FIFO의 단서예요. enqueue는 뒤(rear)에 붙이고 dequeue는 앞(front)에서 꺼내요.','첫 삭제 직전 큐를 [A,B,C,D,E]로 적어요.',{'a':'정답이에요. 앞에서 차례로 삭제하면 A→B→C→D→E예요.','b':'E부터 꺼내는 것은 스택의 LIFO예요. 큐의 첫 삭제 A와 달라요.','c':'처음 세 글자는 맞지만 D가 E보다 먼저 들어왔으므로 끝 두 글자를 바꿀 수 없어요.','d':'B가 A보다 먼저 나가면 먼저 들어온 A를 건너뛰므로 FIFO를 위반해요.'},{'a':'다섯 삭제 뒤 큐는 빈 상태이고 출력은 ABCDE예요.','b':'첫 출력만 비교해도 E≠A로 배제돼요.','c':'네 번째 삭제는 D여야 하므로 E가 나오는 보기를 배제해요.','d':'첫 삭제가 A여야 하므로 B가 나오는 보기를 배제해요.'},'큐와 스택을 혼동하지 않아요. 보기 a~d를 각각 비교하되 답은 하나예요.','FIFO → (a) ABCDE')
add('foo','코드가 어떤 문제를 푸는지 이름이 아니라 인자 변화로 판단해요. 입력은 양의 정수 x,y로 두어요.','x%y라는 “나머지”와 (y,x%y) 호출은 Euclidean algorithm의 단서예요. x=qy+r일 때 x,y의 공약수 집합은 y,r의 공약수 집합과 같아요. y>0일 때 0≤r&lt;y예요.','foo(48,18)에서 나머지 12를 첫 줄에 적어요.','(48,18)→(18,12)→(12,6)에서 나머지가 0이 되어 6을 반환해요. 공약수 d가 x,y를 나누면 x−qy=r도 나누고, 반대로 y,r을 나누면 qy+r=x도 나눠요. 그래서 매 호출의 최대공약수가 같아요. 나머지가 양의 이전 y보다 작아 종료해요.','48의 약수와 18의 약수 중 공통 최대는 6이에요. 순서를 바꾼 foo(18,48)도 (48,18)로 이어져 6이에요. 따라서 답은 최대공약수 GCD예요.','원 함수는 y=0에서 %0이므로 정의되지 않아요. 양의 입력 조건 없이 모든 정수에 안전하다고 쓰지 않아요.','나머지로 줄이는 유클리드 호제법')
add('gcd','빈 gcd 본문을 채워 양의 두 정수의 최대공약수를 반환해요.','“순환 함수”와 “최대공약수”에서 gcd(i,j)=gcd(j,i%j)를 떠올려요. %를 계산하기 전에 j=0을 검사해야 나눗셈 오류 없이 종료해요.',code('if (j == 0) return i;'),code('int gcd(int i, int j) {\n    if (j == 0) return i;\n    return gcd(j, i % j);\n}'),'gcd(48,18)→(18,12)→(12,6)→(6,0)→6이에요. 반환값은 추가 계산 없이 위 호출로 전달돼요. 공약수 집합 보존과 두 번째 인자의 감소가 정확성과 종료를 증명해요. 입력 변환 성공과 양의 int 범위를 가정해요.','if 앞에서 i%j를 계산하면 마지막 호출에서 %0을 하게 돼요. “0이 모든 수를 나눈다”가 아니라 모든 양의 수가 0을 나눈다는 뜻이에요.','j=0 종료, 아니면 gcd(j,i%j)')
add('recursion','함수가 자기 자신을 호출한다는 설명에 맞는 이름을 쓰는 문제예요.','“자기 자신을 다시 호출”은 recursion, 수업 용어로 순환(재귀)이에요. 일반 반복 iteration은 루프를 돌지만 별도의 자기 호출을 만들지 않아요.','빈칸에 순환(recursion)을 적어요.','답은 순환, 또는 동의어 재귀예요. 예를 들어 factorial(3)이 factorial(2)를 호출하면 작은 문제의 답을 받아 현재 답을 만들어요. 올바른 순환은 즉시 답을 주는 바닥 조건과 그 조건으로 다가가는 감소를 함께 가져요.','반복문만 있는 sum은 자기 호출이 없어요. 반대로 함수 안의 자기 호출은 루프가 없어도 순환이에요. 이 차이로 용어를 확인해요.','함수 이름을 두 번 썼다고 항상 실행 중 자기 호출은 아니에요. 실제 호출 관계를 보아요.','자기 호출 = 순환/재귀')
add('binary','예시 10을 1010으로 출력하도록 dec_to_bin의 순환 본문을 채워요. 여기서는 양의 정수 입력을 기본으로 두어요.','n=2q+r, r∈{0,1}에서 r=n%2는 맨 오른쪽 비트예요. 높은 자리 q=n/2를 먼저 출력해야 왼쪽부터 읽는 이진수(binary)가 돼요.',code('if (n == 0) return;'),code('void dec_to_bin(int n) {\n    if (n == 0) return;\n    dec_to_bin(n / 2);\n    printf("%d", n % 2);\n}'),'10→5→2→1→0으로 호출해요. 복귀할 때 1%2=1, 2%2=0, 5%2=1, 10%2=0을 출력하여 1010이에요. 1×8+0×4+1×2+0=10으로 역변환해 확인해요. 이 본문은 입력 0에 아무것도 출력하지 않으므로 0도 허용하려면 호출부에서 printf("0") 처리가 별도로 필요해요. 음수는 범위 밖이에요.','printf를 순환 호출보다 먼저 쓰면 끝자리부터 출력해서 10에서 0101이 돼요.','n/2 먼저 호출, 돌아와 n%2 출력')
for count in (10,20,30):
 add('tri'+str(count),'대입문 실행 횟수만 세어요. n은 비음수 정수이고 배열의 유효한 접근 범위를 가정해요.','j가 i부터 시작하므로 각 i의 j 반복 횟수는 n−i예요. k는 입력과 무관한 상수 '+str(count)+'번이에요. 중첩 개수만 보고 n³이라고 판단하지 않아요.','i=0일 때 j는 n번, i=1일 때 n−1번이라고 적어요.',f'T(n)={count}×[n+(n−1)+…+1]={count}n(n+1)/2예요. 상수와 낮은 차수를 지우면 O(n²), 더 정확한 성장률은 Θ(n²)이에요. 합 공식은 앞뒤 항을 짝지으면 각 쌍의 합이 n+1인 데서 나와요.',f'n=3이면 j 횟수는 3+2+1=6이라 대입은 {count*6}번이에요. n=0에서는 0번, n=1에서는 {count}번으로 공식과 맞아요. 별도 반복문으로 n=0..20의 횟수를 확인해요.','변형 카드의 k 상수와 아래 기출 원문 30을 구별해요. 답은 현재 카드의 상수로 계산해요.','상수×삼각수, O(n²)')
for count in (10,20,30):
 add('four'+str(count),'p가 등장하지만 실제로 바뀌는 변수는 j예요. k=1에서 '+str(count-1)+'번 대입해요.','for문의 변수 이름보다 조건과 증감식을 읽어요. j≤i 동안 j++하므로 각 i에서 j=1..i를 한 번 훑어요. 바깥 j 루프는 그 뒤 j=i+2에서 계속되지만 j≤i가 거짓이라 대입을 추가하지 않아요.','i=1일 때 안쪽 j=1에서 한 번 진입한다고 적어요.',f'i=1..n−1의 안쪽 실행 횟수는 1+2+…+(n−1)예요. 각 실행에 k는 1..{count-1}라 {count-1}번이므로 T(n)={count-1}n(n−1)/2, O(n²)예요. p는 1에서 변하지 않아도 j가 증가하므로 이 루프의 종료를 막지 않아요.',f'n=4에서 i별 대입 횟수는 {count-1},{2*(count-1)},{3*(count-1)}, 합 {6*(count-1)}이에요. n=1은 0번이에요. 별도 제어흐름 시뮬레이션과 공식이 일치해요.','네 겹이라고 n⁴이 아니에요. k=1이므로 k&lt;'+str(count)+'는 '+str(count-1)+'번이에요. 원문의 대입값 1과 설명의 0 차이는 횟수를 바꾸지 않아요.','j 증감 추적, (k끝−1)×삼각수')
add('broken-loop','원문 넷째 루프는 i++인데 k&lt;30을 검사해요. 현재 리뷰는 k++로 보는 가정을 별도로 명시했어요. 두 경우를 나눠요.','종료 조건을 검사하는 k가 변하는지 먼저 확인해요. 원문의 결함과 수정 가정의 시간 복잡도를 같은 답으로 취급할 수 없어요. 원 코드 실행은 정상적인 T(n) 계산 대상이 아니에요.','원문: i=1,j=0,k=0에서 넷째 루프 진입이라고 적어요.','원문 그대로라면 k=0이 계속되어 k&lt;30이 항상 참이에요. i만 증가해 배열 밖 접근이나 정수 범위 초과에 이르므로 정상 종료와 유한한 T(n)을 보장하지 않아요. n≤1은 대입 0번이지만 n≥2의 정상 빅오 답은 정할 수 없어요. <strong>리뷰가 명시한 k++ 가정에서만</strong> j가 0..i−1로 증가하고 k가 30번 돌아 T(n)=30n(n−1)/2, O(n²)이에요. 셋째 루프의 j 증감은 그대로 두어요.','수정 가정 n=4의 i별 횟수는 0,30,60,90으로 180번이에요. 원문은 k가 변하지 않는다는 정적 제어흐름 분석으로 결함을 확인하며 실제 위험 코드는 실행하지 않아요. 이 180을 원문 실행 결과라고 쓰지 않아요.','문제은행의 의도된 답을 원문의 정상 실행값으로 승인하지 않아요. 이 해설은 결함과 조건부 답을 설명하는 것이며 원 코드의 정상 실행 검증은 보류 상태예요.','원문 정상 복잡도 없음; k++ 가정만 O(n²)')
add('ch01-q12','입력 크기 n이 충분히 커질 때의 대표 성장률을 작은 순서로 나열해요.','Big O는 점근 상한 표기예요. 여기서는 문제에서 제시한 대표 함수들의 성장률 비교를 요구해요. log의 밑은 1보다 큰 고정 상수이며 순서를 바꾸지 않아요.','상수 1과 log n을 먼저 적어요.','O(1), O(log n), O(n), O(n log n), O(n²), O(2ⁿ), O(n!) 순서예요. log n/n→0이고 log n&lt;n인 충분히 큰 n에서 n log n&lt;n²이에요. 지수는 어떤 고정 차수 다항식보다 커지고, n!/2ⁿ는 뒤쪽 인수들의 곱이 계속 커져 발산해요.','n=16에서 1,4,16,64,256,65536,20922789888000 순서예요. 이 예는 직관 확인이고 전체 점근 순서는 앞의 성장률 논증이 근거예요. 실제 초 단위 시간은 상수·하드웨어에 따라 달라요.','작은 n의 한 번 비교를 일반 증명으로 삼지 않아요. O(n²) 클래스는 O(n)도 포함하므로 여기서는 대표 성장 함수 비교라는 관례로 읽어요.','1&lt;log n&lt;n&lt;n log n&lt;n²&lt;2ⁿ&lt;n!')
add('ch01-q09','T(n)=7n+10이 무엇을 세는지 고르는 문제예요.','“시간 복잡도 함수”는 기준 기본 연산(operation)의 실행 횟수를 입력 크기 n의 함수로 표현한 것이에요. 같은 연산을 같은 비용으로 세는 모형이며 실제 초 단위 실행 시간과 같지는 않아요.','n=3일 때 T(3)=31회라고 적어요.','정답은 (1) 연산의 횟수예요. 입력 개수 n에 비례하는 7n회와 입력에 무관한 10회를 더한 식이에요. 메모리 사용량이면 공간 복잡도이고 입력 개수 자체는 n이에요.','n=0→10회, n=1→17회, n=2→24회로 입력 1개 증가마다 7회 늘어요. 함수의 단위가 “연산 회수”인지 확인해요.','7n+10을 7n+10초라고 말하려면 각 연산의 시간에 대한 별도 가정이 필요해요.','시간 복잡도는 연산 횟수')
add('ch02-q01','factorial(5) 실행 중 동시에 살아 있는 호출 기록의 최대 수를 세어요.','“동시에”는 활성 레코드 activation record와 호출 스택의 깊이를 묻는 단서예요. 강의록 factorial은 n≤1이면 반환하므로 factorial(0)을 추가로 부르지 않아요.','호출 줄에 5→4→3→2→1을 적어요.','5개의 factorial 호출이 살아 있는 순간이 최대예요. 5,4,3,2의 호출은 곱셈 결과를 기다리고 1의 호출이 바닥 답 1을 결정해요. 이후 복귀하면서 1,2,6,24,120을 전달하고 기록을 하나씩 없애요.','바닥 n≤1 코드와 대조하면 입력 1은 깊이 1, 입력 2는 깊이 2예요. 입력 5의 깊이는 5예요. main의 기록은 factorial의 기록이 아니므로 세지 않아요.','n=0을 바닥으로 삼는 다른 구현의 깊이 6을 현재 강의 코드에 섞지 않아요.','강의 바닥 1 → 최대 5개')
add('ch02-q05','잘못된 순환 함수의 결함을 찾는 문제예요. 정상 반환값을 요구하는 문제가 아니에요.','“잘못된 점”과 recursive(n)은 종료를 위한 감소가 없는 단서예요. 바닥 조건 n==1은 있지만 n이 변하지 않으면 그 조건에 가까워지지 않아요.','n=2에서 2×recursive(2)를 적어요.','2→2→2…가 반복되어 결과를 얻지 못해요. n=1에서는 0을 반환하지만 n>1은 종료 조건에 도달하지 않아요. 결함은 인자를 줄이지 않는 자기 호출이에요. 팩토리얼 의도라면 recursive(n−1)와 바닥값 1이 함께 필요하지만 이는 수정안이지 원문 답이 아니에요.','인자가 동일하다는 정적 추적이 모든 n≠1에서 동일 상황 반복을 보여 줘요. 시스템 자원 한계나 signed overflow에 따른 실제 동작을 정상 결과로 예측하지 않아요.','바닥 조건이 존재한다는 것만으로 종료를 보장하지 않아요.','같은 n 재호출 → 감소 없음')
add('ch02-q06','이 함수에서 빠진 종료 장치를 찾는 문제예요.','인자가 n−1로 줄어도 멈추는 base case가 없으면 순환은 끝나지 않아요. 종료에는 감소와 즉시 반환 조건이 둘 다 필요해요.','recursive(2)→recursive(1)→recursive(0)을 적어요.','조건문 없이 계속 호출하므로 2→1→0→−1…로 내려가요. 잘못된 점은 바닥 조건 누락이에요. 유한한 정답 반환값은 없고 자원 고갈·정수 범위 한계에 도달할 수 있어요. 팩토리얼이라면 n≤1에서 1을 반환하는 분기가 필요해요.','본문에 자기 호출 없이 return하는 경로가 하나도 없는 것을 확인해요. 감소하는 인자만으로는 종료 증명이 완성되지 않아요. 위험한 원 코드를 실행해 특정 크래시 값을 정답으로 삼지 않아요.','0을 찍었다고 자동으로 종료하는 것이 아니에요.','바닥 조건 없음 → 정상 반환 보장 없음')
add('ch02-q09','recursive(10)의 화면 출력 순서와 반환값을 각각 구해요.','printf는 호출 앞에 있으므로 내려갈 때 출력해요. +1은 호출이 끝난 뒤 더하므로 복귀할 때 계산해요. n&lt;1이면 −1이라는 base case예요.','출력의 첫 줄 10을 적고 다음 인자 7을 계산해요.','출력은 줄마다 10,7,4,1,−2예요. −2도 조건 검사 전에 출력해요. 바닥 반환 −1에서 1의 호출은 0, 4의 호출은 1, 7의 호출은 2, 10의 호출은 3을 반환해요. 따라서 최종 반환값은 3이에요.','10−3×4=−2라 재귀 간선이 4개예요. 바닥 반환 −1+4=3으로 별도 검산해요. 출력된 숫자 5개와 반환 덧셈 4회를 구별해요.','n=1은 n&lt;1을 만족하지 않으므로 한 번 더 호출해요.','출력 10,7,4,1,−2 / 반환 3')
add('ch02-q13','양의 정수 n까지의 합을 순환으로 계산해요.','“순환적인 프로그램”에서 S(n)=n+S(n−1), S(1)=1을 떠올려요. 큰 합을 마지막 항과 앞의 합으로 분해해요.',code('if (n == 1) return 1;'),code('int sum(int n) {\n    if (n == 1) return 1;\n    return n + sum(n - 1);\n}'),'n=4에서 4+3+2+1=10이에요. 귀납적으로 sum(n−1)이 1..n−1의 합이면 현재 n을 더해 1..n의 합이 돼요. n은 양의 정수이며 결과가 int에 표현 가능하다고 가정해요.','n≤0 입력에 이 바닥 조건을 그대로 쓰면 정상 종료가 안 돼요. 입력 범위를 적어요.','바닥 1, n+sum(n−1)')
add('ch02-q16','원래 sum의 결과를 유지하면서 자기 호출을 반복문으로 바꿔요.','“비순환적”은 accumulator와 loop의 단서예요. 원 코드가 양의 n에서 더한 항 1..n을 반복문도 한 번씩 더하면 같아요.',code('int total = 0;'),code('int sum(int n) {\n    int total = 0;\n    for (int i = 1; i <= n; ++i) total += i;\n    return total;\n}'),'n=1→1, n=4→10으로 원 순환과 같아요. 각 i 뒤 total=1+…+i 불변식이 모든 양의 입력의 동일성을 보장해요. 계산이 int 범위 안이고 i++도 범위를 넘지 않는 입력을 가정해요.','순환이 아닌 코드를 요구하므로 본문에서 sum을 다시 부르면 안 돼요. n≤0은 원 코드의 정의된 입력이 아니에요.','0에서 1..n 누적, 호출 제거')
add('ch03-q01','10행 20열의 int 배열 전체 바이트 수를 구해요. int=4바이트는 문제에서 정한 값이에요.','“배열이 차지하는 공간”은 원소 개수×원소 한 개의 크기예요. 배열은 같은 타입 원소를 연속 배치하므로 별도 행 포인터 10개가 붙는 것이 아니에요.','원소 수=10×20=200을 적어요.','200×4=800바이트, 정답 (4)예요. 각 행이 20×4=80바이트이고 10행을 합쳐도 800이에요.','두 방식 200원소×4와 10행×80이 같아요. 실제 C 검산에서도 sizeof(int)==4인 환경의 sizeof a가 800이에요.','10+20으로 원소 수를 세거나 int**의 저장 크기와 섞지 않아요.','행×열×int 크기 = 800')
add('ch03-q04','two[0]부터 two[9]까지 2⁰..2⁹를 저장하고 출력해요.','“이전 값의 두 배”라는 점화식 two[i]=2×two[i−1]로 거듭제곱 power를 만들 수 있어요. C의 ^는 거듭제곱이 아니라 XOR이므로 쓰지 않아요.',code('int two[10];\ntwo[0] = 1;'),code('#include <stdio.h>\nint main(void) {\n    int two[10];\n    two[0] = 1;\n    for (int i=1; i<10; ++i) two[i] = 2*two[i-1];\n    for (int i=0; i<10; ++i) printf("%d%s", two[i], i==9?"\\n":" ");\n    return 0;\n}'),'출력은 1 2 4 8 16 32 64 128 256 512예요. 귀납적으로 첫 원소 2⁰이고 직전 2ⁱ⁻¹의 두 배가 2ⁱ예요. 독립 정수 거듭제곱과 C 출력 모두 대조해요.','i=0부터 직전 원소를 읽으면 two[−1]로 배열 범위를 벗어나요.','two[0]=1, 이전 원소×2')
add('ch03-q05','이름·나이·월급을 한 사람의 구조체로 묶어요.','서로 다른 타입 필드는 structure의 단서예요. name은 문자 배열 char[], age는 int, salary는 문제에서 지정한 float예요.','struct person { 를 먼저 적어요.',code('struct person {\n    char name[100];\n    int age;\n    float salary;\n};'),'세 필드의 타입과 이름을 요구사항과 하나씩 대조해요. name의 100칸은 설계 선택이며 최대 99바이트와 종료 널을 보관해요. 문제는 길이를 지정하지 않아 다른 적절한 길이도 가능해요. C 컴파일로 멤버 접근과 선언을 확인해요.','서로 다른 필드를 int 배열 하나로 대신하지 않아요. 구조체 선언 끝의 세미콜론도 필요해요.','char name[], int age, float salary')
add('ch03-q06','실수부와 허수부를 갖는 타입 complex를 만들고 두 변수를 선언해요.','typedef는 새로운 표현을 발명하는 것이 아니라 기존 타입에 이름 alias를 붙여요. real과 imaginary는 float, c1과 c2는 이 두 필드를 갖는 객체예요.','typedef struct { 로 시작해요.',code('typedef struct {\n    float real;\n    float imaginary;\n} complex;\ncomplex c1, c2;'),'complex c1,c2는 각각 두 float 멤버를 가진 변수를 만들어요. C 컴파일에서 c1.real=1.0f, c2.imaginary=2.0f 접근이 가능해요. typedef 선언만으로는 c1,c2 객체가 생기지 않으므로 별도 선언을 확인해요.','complex를 구조체 태그와 변수 이름으로 혼동하지 않아요.','typedef 별명 뒤 변수 c1,c2 선언')
add('ch03-q03','네 배열의 전체 크기를 주어진 검산 환경의 바이트 수로 비교해요.','sizeof는 byte 단위의 객체 크기예요. array 크기는 원소 수×sizeof(타입)이에요. 여기의 int=4,double=8,char=1,float=4는 현재 환경 조건이에요.','array1=10×4=40바이트라고 적어요.','array1=40, array2=80, array3=40, array4=40바이트예요. 최대는 (2) double array2[10]이에요.','C sizeof 출력에서 40,80,40,40을 독립 확인해요. 현재 타입 크기 전제가 바뀌면 비교도 다시 해야 하므로 모든 C 구현에 8바이트 double을 단정하지 않아요.','원소 개수만 비교하면 char[40]을 고르게 돼요.','개수×타입 크기 → double[10] 80')
add('ch03-q07','두 복소수 a,b를 받고 합을 Complex 값으로 반환해요.','real+imag×i의 합은 같은 성분끼리 더하는 componentwise addition이에요. C 구조체는 값으로 전달·반환할 수 있어요. 여기서는 멤버 이름을 real,imag로 정의해요.',code('Complex result;'),code('typedef struct { float real, imag; } Complex;\nComplex complex_add(Complex a, Complex b) {\n    Complex result;\n    result.real = a.real + b.real;\n    result.imag = a.imag + b.imag;\n    return result;\n}'),'a=(1,2),b=(3,4)이면 result=(4,6), 즉 4+6i예요. 실수부와 허수부를 별도로 확인해요. 함수는 복사본을 받으므로 result 계산이 호출자의 a,b를 변경하지 않아요. 부동소수점 일반 입력은 반올림될 수 있어요.','real과 imag를 섞어 더하거나 지역 result의 주소를 반환하지 않아요.','같은 성분끼리 합, 구조체 값 반환')
add('ch03-q12','구조체 하나를 heap에 만들고 100과 문자열을 저장한 뒤 반납해요.','동적 할당 dynamic allocation은 malloc(sizeof *p), 실패는 NULL, 멤버 접근은 p->field, 해제는 free(p)예요. 최대 20문자를 보관하려고 종료 널을 포함한 21칸을 선택해요.',code('struct Item { int number; char text[21]; };'),code('#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nstruct Item { int number; char text[21]; };\nint main(void) {\n    struct Item *p = malloc(sizeof *p);\n    if (p == NULL) return 1;\n    p->number = 100;\n    strcpy(p->text, "just testing");\n    printf("%d %s\\n", p->number, p->text);\n    free(p);\n    return 0;\n}'),'just testing은 12문자라 종료 널까지 13칸으로 21칸 안에 들어가요. C 출력은 100 just testing이고 성공한 malloc 1회와 free 1회가 짝이에요. 문자열 한계가 널 포함 20칸이라는 해석에서도 이 예시는 20칸에 들어가요.','sizeof p는 포인터 크기여서 구조체 크기가 아니에요. free 뒤 p->number를 읽지 않아요.','malloc(sizeof *p) → NULL 검사 → 저장 → free')
add('ch01-q17','배열 인덱스 접근, 최솟값 찾기, 합의 최선·최악 시간 복잡도를 각각 구해요.','배열은 random access라 주소=시작주소+인덱스×원소크기로 바로 찾아요. 정렬 등 추가 정보가 없는 임의의 배열에서 최솟값과 합은 모든 값을 봐야 해요. n은 여기서 전체 원소 수예요.','세 행 표에 접근 / 최소 / 합을 적어요.','(1) n번째 원소 출력: 최선·최악 O(1)이에요. 유효 인덱스 접근과 정수 출력의 비용을 상수로 세어요. (2) 최소: 첫 원소를 후보로 놓고 나머지 n−1개를 비교하므로 최선·최악 O(n)이에요. (3) 합: n개를 읽어 누적하므로 최선·최악 O(n)이에요.','아직 읽지 않은 한 값을 더 작게 바꾸면 최소가 바뀌고, 어떤 값도 바꾸면 합이 바뀔 수 있어요. 그러므로 임의 배열에서 생략한 원소가 있는 정확한 알고리즘은 불가능해요. 이미 정렬됨 같은 추가 가정은 원문에 없어요.','최소가 첫 칸에 있어도 그 사실을 확인하려면 나머지를 읽어야 해요.','접근 O(1), 최소·합 O(n), 최선=최악')
add('ch03-q08','현재 items개를 저장한 여유 있는 배열에서 loc에 새 값을 넣어요. items는 원문 인자에 없어서 전역으로 두어요.','삽입 insertion은 빈 칸을 만들기 위해 뒤 원소를 오른쪽으로 옮겨요. 뒤에서부터 복사해야 아직 필요한 값을 덮어쓰지 않아요. 전제는 0≤loc≤items&lt;용량이에요.',code('for (int i = items-1; i >= loc; --i)'),code('int items; /* 현재 길이: 호출 전에 설정 */\nvoid insert(int array[], int loc, int value) {\n    for (int i=items-1; i>=loc; --i)\n        array[i+1] = array[i];\n    array[loc] = value;\n    ++items;\n}'),'[10,20,30],items=3,loc=1,value=99에서 30→칸3,20→칸2 후 [10,99,20,30],items=4예요. 원래 loc 이상인 각 원소 k는 k+1로 이동하고 이전 원소의 순서는 유지돼요. 끝 loc=items이면 이동 0번이에요.','앞에서 오른쪽으로 복사하면 다음 원소가 덮여 같은 값이 반복돼요. 용량 초과와 잘못된 loc은 호출 전에 거부해요.','뒤→앞 복사, loc 저장, 길이 증가')
add('ch03-q09','바로 앞 insert의 이동 횟수로 시간 복잡도를 구해요. 용량 n과 현재 길이 items를 구분해요.','for 인덱스는 items−1에서 loc까지 양끝 포함이라 반복 횟수는 items−loc예요. 원소 이동마다 상수 비용이고 마지막 저장·길이 증가도 상수예요.','이동 횟수=items−loc를 적어요.','T=상수×(items−loc)+상수예요. 첫 위치 loc=0의 최악은 O(items), 끝 loc=items의 최선은 O(1)이에요. 현재 길이를 n이라 부르는 관례에서는 최악 O(n)이지만 이 원문의 n은 배열 용량이에요.','items=3일 때 loc=0,1,2,3의 이동 횟수는 3,2,1,0이에요. 독립 C 이동 추적과 비교해요.','용량이 크더라도 사용하지 않는 빈 칸을 모두 이동하지 않아요.','최악 O(items), 끝 O(1)')
add('ch03-q10','loc의 값을 삭제하고 그 값을 반환해요. 뒤 원소들을 앞으로 당긴 후 길이를 줄여요.','삭제 deletion는 원소의 논리적 길이를 줄이는 연산이에요. 0≤loc&lt;items 전제에서 먼저 삭제값을 저장해야 이동으로 덮여도 반환할 수 있어요. 왼쪽 복사는 앞에서 뒤 순서예요.',code('int removed = array[loc];'),code('int items;\nint delete(int array[], int loc) {\n    int removed = array[loc];\n    for (int i=loc; i<items-1; ++i)\n        array[i] = array[i+1];\n    --items;\n    return removed;\n}'),'[10,20,30,40],loc=1이면 removed=20, 칸1←30,칸2←40 후 items=3이며 유효 목록은 [10,30,40]이에요. 마지막 메모리 40이 남아도 길이 밖이라 목록 원소가 아니에요. 삭제 전후 순서와 반환 20을 별도 확인해요.','길이를 먼저 줄여 잘못된 끝 조건을 쓰거나 삭제값을 이동 후 읽으면 답이 바뀌어요. 이 코드는 C이며 C++의 delete 예약어와 혼동하지 않아요.','값 저장 → 앞 이동 → 길이 감소 → 반환')
add('ch03-q11','앞 delete 함수의 이동 횟수를 세어요.','i=loc..items−2라 이동 횟수는 items−loc−1이에요. 삭제값 저장·길이 감소·반환은 상수 비용이에요.','이동 횟수=items−loc−1을 적어요.','첫 원소 loc=0을 지우면 items−1번 이동하여 최악 O(items)예요. 끝 loc=items−1이면 이동 없이 O(1)이에요. 현재 길이와 용량 n을 구별해요.','items=4에서 loc=0,1,2,3이면 이동은 3,2,1,0번이에요. 삽입과 달리 삭제 위치 자신의 값은 이동 대상이 아니라서 한 번 적어요.','삽입의 items−loc를 그대로 쓰지 않아요.','최악 O(items), 끝 O(1)')
add('ch06-q03','last가 실제 마지막 노드를 가리킨다는 조건에서 참인 식을 고르세요.','연결 리스트 linked list는 다음 노드 주소를 link에 저장해요. 마지막 노드는 존재하되 다음 노드가 없어서 link만 NULL이에요. last 자체와 last->link는 서로 다른 값이에요.','last → [data | NULL]을 그려요.','정답 (3) last->link==NULL이에요. (1)은 노드가 없다는 뜻이므로 조건과 달라요. (2)의 data는 저장 데이터이며 마지막 여부와 무관해요. (4)는 NULL인 last->link를 다시 역참조해서 안전하게 참·거짓을 평가할 수 없어요.','한 노드 리스트에서도 last는 노드 주소이고 link는 NULL이에요. data=7인 예에서는 (2)도 거짓이며 끝 노드 규칙은 data와 관계없이 유지돼요.','NULL->link를 읽어 판단하지 않아요. last가 NULL인 빈 리스트는 주어진 조건 밖이에요.','마지막 노드의 link만 NULL')
add('ch06-q04','현재 노드 다음의 노드 주소를 p에 넣는 문장을 골라요. p는 유효한 노드 주소여야 해요.','노드가 따로 할당되어 연속 주소라는 보장이 없으므로 pointer arithmetic보다 저장된 link를 따라가야 해요. p->link는 다음 노드 주소이고 p->data는 데이터예요.','현재 A 주소와 A.link에 들어 있는 B 주소를 적어요.',{'a':'p++는 구조체 한 개 크기만큼 주소를 증가시켜요. 다음 노드가 그 위치에 있다는 보장은 없어요.','b':'p--는 구조체 한 개 크기만큼 감소시켜요. 다음 노드 연결과 무관해요.','c':'p=p->link가 정답이에요. 현재 노드가 저장한 다음 주소를 읽어 p에 대입해요.','d':'p=p->data는 데이터 필드를 주소인 것처럼 대입해요. int 데이터라면 포인터 타입과도 맞지 않아요.'},{'a':'A=주소1000,B=주소9000 예에서 p++는 B를 얻지 못해요. 숫자 주소는 개념 그림이며 실제 C 정수-주소 산술 예제가 아니에요.','b':'같은 예에서 주소 감소도 B에 닿는다는 규칙이 없어요.','c':'A.link=B 주소를 대입하면 p는 정확히 B가 돼요. 마지막에서는 NULL이 돼요.','d':'A.data=5라도 다음 주소 B와 관계없어요.'},'p가 NULL이면 p->link 자체가 안전하지 않아요. 이동 전에 p!=NULL을 검사해요.','다음 주소 p=p->link')
add('ch06-q07','A→B→C→D→NULL에서 for 종료 후 p가 가리키는 노드를 구해요. 빈 리스트는 그림의 조건이 아니에요.','조건은 p!=NULL이 아니라 p->link!=NULL이에요. 현재 노드의 다음 주소가 없을 때 현재 노드에서 멈춰요. 빈 본문 뒤 세미콜론도 반복문 본문이에요.','p=A, A.link=B≠NULL을 적어요.','A에서 조건 참→B, B에서 참→C, C에서 참→D, D에서는 link=NULL이라 거짓이에요. 따라서 답은 D 노드예요. p를 NULL까지 이동시키지 않아요.','각 검사 시점의 p는 A,B,C,D로 네 번이고 이동은 세 번이에요. 한 노드인 경우 첫 조건이 거짓으로 그 노드에서 멈추는 규칙도 같아요.','head=NULL일 때 이 코드의 p->link는 UB예요. 주어진 비어 있지 않은 그림에서만 계산해요.','다음 링크 검사 → 마지막 D에서 정지')
add('ch06-q10','입력 노드들을 연결하고 head에서 출발해 실제 노드 수를 세는 프로그램을 만들어요.','linked list traversal은 link를 따라 NULL까지 방문하는 것이에요. 입력으로 받은 n을 그대로 결과로 쓰는 대신 실제 연결 구조를 세어야 해요. count는 방문한 노드 수예요.',code('int count = 0;'),code('#include <stdio.h>\n#include <stdlib.h>\ntypedef struct Node { int data; struct Node *link; } Node;\nint count_nodes(const Node *head) {\n    int count=0;\n    for (const Node *p=head; p!=NULL; p=p->link) ++count;\n    return count;\n}\nint main(void) {\n    int n, value, ok=1;\n    Node *head=NULL, *tail=NULL;\n    printf("노드의 개수 : ");\n    if (scanf("%d", &n)!=1 || n<0 || n>10000) return 1;\n    for (int i=0; i<n; ++i) {\n        printf("노드 #%d 데이터 : ", i+1);\n        if (scanf("%d", &value)!=1) { ok=0; break; }\n        Node *node=malloc(sizeof *node);\n        if (node==NULL) { ok=0; break; }\n        node->data=value; node->link=NULL;\n        if (tail) tail->link=node; else head=node;\n        tail=node;\n    }\n    if (ok) printf("연결 리스트 노드의 개수 = %d\\n", count_nodes(head));\n    while (head) { Node *next=head->link; free(head); head=next; }\n    return ok?0:1;\n}'),'입력 3,5,6,7로 5→6→7→NULL이 만들어져 count는 0→1→2→3이에요. 빈 입력 n=0에서는 0이에요. count가 이미 방문한 접두 노드 수라는 불변식으로 acyclic 리스트의 정확성을 확인해요. 10000 제한은 검산 프로그램의 입력 보호 선택이에요.','마지막 노드도 세어야 하므로 조건을 p->link!=NULL로 쓰지 않아요. 순환 링크를 가진 구조는 이 단순 리스트 전제 밖이에요.','head부터 p!=NULL 동안 한 노드당 +1')
add('ch04-q01','배열 스택의 push 성공 뒤 top 변화식을 고르는 문제예요.','top은 마지막 유효 원소의 index예요. push는 더 높은 빈 칸을 한 칸 사용하므로 top+1로 바뀌어요. 먼저 full 여부를 확인하는 전제예요.','빈 스택 top=−1을 적어요.','첫 push 후 top=0, 다음 후 1이에요. 따라서 (4) top=top+1이 정답이에요. 증가시킨 칸에 새 원소를 저장하므로 top이 최신 원소를 가리킨다는 불변식이 유지돼요.','두 push의 원소 수 2는 top=1과 size=top+1 규칙으로 같아요. 포화 상태에서는 정상 push가 일어나지 않고 top을 증가시키면 안 돼요.','top=0은 첫 push의 사례일 뿐 일반 변화식이 아니에요.','push 성공 → top+1')
add('ch04-q04','top=3일 때 저장된 원소 개수를 구해요.','0부터 시작하는 배열 index와 count를 구분해요. 인덱스 0..top을 양끝 포함하면 top−0+1개예요.','유효 칸 0,1,2,3을 적어요.','네 칸이므로 (4) 4개예요. 일반식 size=top+1이에요.','top=−1이면 0개, top=0이면 1개로 초기 상태와 일치해요. top=3에서도 3+1=4예요.','top을 원소 개수로 그대로 답하지 않아요.','size=top+1=4')
add('ch04-q05','배열 스택의 빈 상태와 가득 찬 상태를 각각 골라요.','길이 M=MAX_STACK_SIZE 배열의 유효 index는 0..M−1이에요. top은 마지막 index, 아무 원소가 없을 때는 −1이라는 sentinel이에요.','빈 상태 top=−1을 적어요.','공백은 (1) top==−1, 포화는 (3) top==MAX_STACK_SIZE−1이에요. top==0은 하나 저장된 상태이고 top==M은 배열 밖 인덱스예요.','M=5에서 top=−1이면 size=0, top=4이면 size=5예요. 각각 실제 칸 수와 맞아요.','“가득 참”을 top==M으로 검사하면 이미 범위를 넘어서요.','empty −1, full M−1')
add('ch04-q08','용량 5인 스택에서 모든 연산 뒤 배열 내용과 top을 추적해요.','push는 ++top 칸에 쓰고 pop은 현재 칸을 읽은 다음 --top해요. LIFO이며 pop은 배열 칸을 지우는 연산이 아니므로 물리적 값과 유효 목록을 나눠요.','초기 [미사용,미사용,미사용,미사용,미사용],top=−1을 적어요.','<table><thead><tr><th>연산</th><th>5칸 메모리(기본 구현)</th><th>top</th><th>유효 목록</th></tr></thead><tbody>'+''.join('<tr><td>'+a+'</td><td>'+b+'</td><td>'+c+'</td><td>'+d+'</td></tr>' for a,b,c,d in [('push 1','1,·,·,·,·','0','[1]'),('push 2','1,2,·,·,·','1','[1,2]'),('push 3','1,2,3,·,·','2','[1,2,3]'),('pop→3','1,2,3,·,·','1','[1,2]'),('push 4','1,2,4,·,·','2','[1,2,4]'),('push 5','1,2,4,5,·','3','[1,2,4,5]'),('pop→5','1,2,4,5,·','2','[1,2,4]')])+'</tbody></table><p>·는 초기화되지 않은 미사용 칸이라 읽어서 값을 가정하지 않아요.</p>','push 5회−pop 2회=3개이며 top=2와 size=top+1이 맞아요. 두 반환값은 3,5예요. 독립 배열 구현과 추상 리스트 구현의 모든 단계가 일치해요.','pop 뒤 남아 있는 5를 여전히 유효 원소라고 세지 않아요.','최종 유효 [1,2,4],top=2')
def stacktable(tokens,states):return '<table><thead><tr><th>토큰</th><th>스택 (왼쪽=바닥)</th></tr></thead><tbody>'+''.join(f'<tr><td>{html.escape(t)}</td><td>{s}</td></tr>' for t,s in zip(tokens,states))+'</tbody></table>'
postA=stacktable(['5','6','*','4','2','/','+','1','−'],['[5]','[5,6]','[30]','[30,4]','[30,4,2]','[30,2]','[32]','[32,1]','[31]'])
postB=stacktable(['7','6','2','/','−','5','4','*','+'],['[7]','[7,6]','[7,6,2]','[7,3]','[4]','[4,5]','[4,5,4]','[4,20]','[24]'])
add('2019-mid-q6','변환한 후위식의 계산에 필요한 push와 pop 횟수를 세어요. 최종 결과를 스택에 남긴다는 조건을 꼭 읽어요.','후위식 postfix evaluation에서 피연산자 하나는 push 1회, 이항 연산자 하나는 pop 2회와 결과 push 1회예요. 괄호나 변환용 연산자 스택 횟수는 계산 스택 횟수에 포함하지 않아요.','후위식 5 6 * 4 2 / + 1 −를 적어요.','피연산자 5개+연산 결과 4개로 push=9회예요. 연산자 4개가 각 2개를 꺼내 pop=8회예요. 계산은 30+2−1=31이에요. '+postA,'9−8=1개가 남아 최종 결과 조건을 만족해요. 별도 토큰 처리 시뮬레이션도 push=9,pop=8,스택=[31]이에요.','마지막 결과까지 pop하면 9회가 되지만 문제는 결과를 남겨야 해요.','push 9,pop 8,결과 31 남음')
add('2018-mid-c024-q9','(1)은 식을 후위식으로 변환하고, (2)는 따로 주어진 토큰 표를 계산해요. 두 입력은 다른 식이에요.','괄호→곱셈→덧셈/뺄셈 우선순위와 같은 우선순위의 좌결합을 지켜요. 후위식의 연산자는 먼저 꺼낸 값이 오른쪽, 다음 값이 왼쪽이에요.','(1)의 괄호 (2+4)를 2 4 +로 적어요.','(1) (2+4)*7은 2 4 + 7 *, 6*3은 6 3 *, 뺄셈 뒤 +1을 붙여 <strong>2 4 + 7 * 6 3 * − 1 +</strong>예요. 이 식의 값은 42−18+1=25예요. (2) 표의 토큰은 <strong>5 6 * 4 2 / + 1 −</strong>이며 다음과 같이 최종 31이에요.'+postA,'(1)을 독립 shunting-yard 변환과 계산으로 확인해 25를 얻어요. (2)는 30+2−1=31과 토큰별 스택을 별도로 확인해요. 25와 31이 다른 것은 오류가 아니라 두 소질문의 입력이 다르기 때문이에요.','(1)의 변환식으로 (2)의 표를 채우면 주어진 토큰을 바꾸게 돼요.','(1) 후위식 값25 / (2) 표 최종31')
add('2017-mid-c050-q6','주어진 후위식의 각 토큰 뒤 스택 칸을 채워요.','후위식은 연산자 직전 스택 위 두 항을 결합해요. /와 −는 교환법칙이 없으므로 second=첫 pop,first=둘째 pop으로 first op second를 계산해요.','처음 7을 읽고 스택 [7]을 적어요.','6/2=3을 만들고 7−3=4를 만들어요. 이어 5*4=20을 만들고 4+20=24를 만들어요.'+postB,'별도 중위식 7−6/2+5*4=24와 같아요. 토큰별 연산 전에 두 값이 있는지 확인했고 최종 한 값 24만 남아요.','첫 pop−둘째 pop으로 계산하면 3−7=−4가 돼요.','스택 추적 최종24, pop 순서 주의')
add('2018-mid-c024-q1','괄호 검사에 적합한 자료구조 이름을 쓰세요.','가장 나중에 열린 괄호를 가장 먼저 닫아야 하므로 LIFO인 stack을 떠올려요. 열린 괄호를 미해결 상태로 저장해요.','빈칸에 스택(stack)을 적어요.','여는 괄호는 push, 닫는 괄호는 top과 종류를 비교하고 pop해요. 닫는 순간 빈 스택이거나 종류가 다르면 실패, 전체 후 남아 있어도 실패예요. 예 ([ ])에서 ]는 가장 최근 [와 짝이고 마지막 )는 (와 짝이에요.','([])는 (,[를 쌓고 ],)에서 역순으로 꺼내 끝에 비어요. ([)]는 )를 만났을 때 top=[라 불일치예요. 이 반례로 FIFO 큐가 적합하지 않음을 확인해요.','여는/닫는 개수만 같아도 종류와 순서가 틀릴 수 있어요.','최근 열린 괄호 먼저 닫기 → 스택')
add('2017-mid-c050-q1','후위 표기식 계산에 쓸 자료구조를 고르는 문제예요.','최근에 나온 미결합 피연산자 둘부터 연산하므로 후입선출 stack이 맞아요. 계산한 부분식도 하나의 피연산자로 다시 push해요.','스택(stack)을 적고 2 3 +를 옆에 적어요.','2를 push,3을 push,+에서 3과2를 pop해 5를 push해요. 2 3 + 4 *에서는 5를 유지하다 4와 곱해 20을 다시 쌓아요.','독립 계산 (2+3)*4=20과 스택 결과가 같아요. 부분식의 계산값을 스택에 저장한다는 불변식으로 다음 연산에도 같은 절차를 적용해요.','큐는 오래된 피연산자부터 꺼내 중첩 부분식을 제대로 결합하지 못해요.','후위식 최근 두 값 결합 → 스택')
add('2017-mid-c050-q10','push,pop과 main의 for문 빈칸을 완성해요. 한 자리 숫자와 +,*만 있는 유효 후위식이 입력이라는 조건을 사용해요.','배열 스택의 top은 최신 위치예요. 문자 digit를 값으로 바꾸려면 str[i]−\'0\'을 써요. +,*는 두 값을 pop하고 결과를 push해요. 원 pop의 공백 분기는 반환값이 없으므로 오류 경로를 정상 계산으로 쓰면 안 돼요.',code('/* push else */\ns->stack[++s->top] = item;'),code('/* push else */\ns->stack[++s->top] = item;\n/* pop else */\nitem = s->stack[s->top--];\nreturn item;\n/* main for문 안 */\nif (str[i] == \'+\' || str[i] == \'*\') {\n    op2 = pop(&s);  /* 오른쪽 값 */\n    op1 = pop(&s);  /* 왼쪽 값 */\n    if (str[i] == \'+\') push(&s, op1 + op2);\n    else push(&s, op1 * op2);\n} else {\n    push(&s, str[i] - \'0\');\n}'),'23+4*는 [2]→[2,3]→[5]→[5,4]→[20] 후 main의 마지막 pop이 20을 출력해요. 52*3+는 13이에요. 전체 검산 코드는 evidence의 안전한 완성본을 컴파일해 실행해요. 입력 길이≤99, 모든 연산 전에 원소≥2, 결과는 int 범위 안인 정상 입력을 전제로 해요. 입력 제한 scanf("%99s",str), 공백 오류 종료는 추가 안전 처리이며 빈칸 원문 자체의 보장은 아니에요.','잘못된 후위식·과긴 입력에서 원문 코드가 안전하다고 주장하지 않아요. 여기서 main은 결과를 pop하므로 앞 횟수 문제의 “남기기” 조건과 달라요.','++top 저장, top 읽고--, digit 변환·연산 결과 push')
add('2017-mid-c050-q2','먼저 온 고객이 먼저 서비스를 받는 은행 대기열을 시뮬레이션해요.','“들어온 순서대로 서비스”는 FIFO queue의 단서예요. 고객이 rear에 서고 front 고객이 먼저 나가요.','빈칸에 큐(queue)를 적어요.','A 도착→[A],B 도착→[A,B],C 도착→[A,B,C]이면 서비스 순서는 A,B,C예요. enqueue와 dequeue가 서로 다른 끝에서 동작해 도착 순서를 지켜요.','첫 도착 A의 서비스가 C보다 먼저라는 조건을 확인해요. 스택이면 C부터 나가 대기열 규칙을 위반해요.','우선순위 고객 같은 별도 정책은 원문에 없어요.','은행 도착 순서 유지 → 큐')
add('2019-mid-q4','스택이 FIFO라는 주장과 괄호 검사 이용이라는 주장을 포함한 문장 전체의 O/X를 판단해요.','stack=LIFO, queue=FIFO라는 정의를 먼저 떠올려요. 하나라도 틀린 주장이 있으면 전체 진술은 참이 아니에요.','스택: Last-In First-Out을 적어요.','답은 X예요. 스택이 괄호 검사에 이용되는 부분은 맞지만 “선입선출 특징을 가지는 스택”이라는 앞부분이 틀려요. 스택은 후입선출이에요.','A 다음 B를 push하고 pop하면 B가 나와요. FIFO라면 A여야 하므로 한 번의 반례로 문장 앞부분을 반박해요.','괄호 검사라는 맞는 사례에만 주목해서 O라고 답하지 않아요.','스택은 LIFO → 전체 X')
add('ch05-q03','10,20,30,40,50을 차례로 큐에 넣은 뒤 세 번 삭제해요.','dequeue는 가장 오래 들어 있던 front 항목을 제거하는 FIFO 연산이에요. 삭제 횟수와 남은 길이를 함께 추적해요.','초기 큐 [10,20,30,40,50]을 적어요.','첫 삭제 10→[20,30,40,50],둘째 20→[30,40,50],셋째 30→[40,50]이에요. 남은 항목은 40,50 순서예요.','5개−3개=2개이고 반환값은 10,20,30이에요. 뒤에서 삭제하면 [10,20]이 남지만 그것은 스택 순서예요.','rear에서 제거하지 않아요.','세 dequeue → [40,50]')
add('ch04-q07','후위식 A B E + D * −에서 첫 연산을 찾으세요.','postfix를 왼쪽부터 읽다가 처음 나온 연산자 앞의 가장 최근 피연산자 둘을 사용해요. A가 먼저 나왔다고 첫 연산에 항상 들어가는 것은 아니에요.','첫 세 토큰 뒤 스택 [A,B,E]를 적어요.','첫 연산자 +에서 E를 오른쪽, B를 왼쪽으로 꺼내 B+E를 계산해요. 따라서 (1)이 정답이에요. A는 스택 아래에 그대로 남아요. 이어 (B+E)*D를 만들고 마지막은 A−(B+E)*D예요.','A=10,B=2,E=3,D=1 예에서 첫 결과5,다음5,최종5예요. 첫 연산에 A가 쓰이지 않았음을 토큰 순서와 따로 확인해요.','중위식처럼 우선순위표만 보고 *부터 하지 않아요. 후위식의 토큰 순서가 계산 순서예요.','처음 +는 B+E')
add('ch04-q11','여는 괄호에 새 번호를 주고 닫는 괄호에는 짝인 여는 번호를 출력하는 프로그램이에요. 번호 출력과 괄호식의 유효성 검사는 구별해요.','가장 최근 여는 번호를 닫는 괄호에 붙여야 하므로 stack에 번호를 저장해요. counter는 여는 괄호에서만 증가하고 pop으로 감소시키지 않아요.',code('int next_id=0, top=-1;'),code('#include <stdio.h>\nint main(void) {\n    char expr[101]; int stack[100], top=-1, next_id=0, first=1;\n    printf("수식: ");\n    if (scanf("%100s", expr)!=1) return 1;\n    printf("괄호 수: ");\n    for (int i=0; expr[i]; ++i) {\n        int id;\n        if (expr[i]==\'(\') {\n            id=++next_id; stack[++top]=id;\n        } else if (expr[i]==\')\') {\n            if (top<0) { fprintf(stderr,"짝 없는 닫는 괄호\\n"); return 1; }\n            id=stack[top--];\n        } else continue;\n        printf("%s%d", first?"":" ", id); first=0;\n    }\n    printf("\\n");\n    if (top>=0) fprintf(stderr,"미닫힌 괄호 %d개\\n", top+1);\n    return 0;\n}'),'((())(()))의 출력은 1 2 3 3 2 4 5 5 4 1이에요. ((((()는 1 2 3 4 5 5를 출력하고 미닫힌 번호1..4가 남아요. 두 번째 원문은 균형 잡힌 괄호식이 아니지만 번호 출력은 주어진 예와 같아요. 독립 번호 추적에서 두 문자열 모두 대조해요.','counter를 닫힐 때 줄이면 다음 새 괄호에 이전 번호를 재사용해요. 미닫힘을 정상 균형 상태라고 말하지 않아요.','열면 새 번호 push, 닫으면 짝 번호 pop')
add('ch04-q14','스택 내용을 꺼내지 않고 저장된 개수를 반환하는 size를 구현해요.','top이 마지막 유효 인덱스이므로 원소 수는 top+1이에요. −1은 빈 상태를 나타내는 규칙이며 정상 top 범위는 −1..M−1이에요.',code('return s->top + 1;'),code('int size(const StackType *s) {\n    return s->top + 1;\n}'),'top=−1→0,0→1,3→4,M−1→M이에요. 값을 직접 꺼내 세지 않아 top과 배열이 그대로 보존돼요. 한 번의 덧셈과 반환이라 O(1)이에요.','pop 반복으로 세면 스택 내용이 사라지고 시간도 O(size)가 돼요.','size=top+1, 원본 보존 O(1)')

def key(q):
 s=q['source'];txt=q['conditions_html']
 if s.startswith('textbook-'):return s.removeprefix('textbook-')
 if s=='2019-mid-q8':return 'foo'
 if s=='2018-mid-c024-q15':return 'gcd'
 if s=='2018-mid-c102-q1':return 'recursion'
 if s=='2017-mid-c050-q11':return 'binary'
 if s=='2019-mid-q9':return 'broken-loop'
 if s=='2018-mid-c024-q8':return 'tri'+re.search(r'k\s*&lt;\s*(\d+)',txt)[1] if '&lt;' in txt else 'tri'+re.search(r'k\s*<\s*(\d+)',txt)[1]
 if s=='unk-final-ltk-q1':return 'four'+re.search(r'k\s*(?:&lt;|<)\s*(\d+)',txt)[1]
 return s
heads=['문제를 내 말로 읽어요','이 문제를 봤을 때 떠올릴 개념과 공식','종이에 적을 첫 줄','왜 이렇게 푸는지 함께 따라가요','완성 답과 검산','이 문제에서 조심할 점','설명을 닫고 다시 해 봐요']
for src in sorted(B.glob('*/review-*/source.json')):
 v=json.loads(src.read_text());folder=src.parent
 for q in v['problems']:
  k=key(q);u,r,start,solve,verify,pit,summary=D[k]
  def parts(body):return ''.join('<div data-subpart="'+s+'">'+(body[s] if isinstance(body,dict) else (body if '<p>' in body or '<pre>' in body or '<table>' in body else p(body)))+'</div>' for s in q['subparts'])
  body=[p(u),p(r),start if '<pre>' in start else p(start),parts(solve),parts(verify),p(pit),'<ol><li>'+html.escape(html.unescape(re.sub('<[^>]+>','',start)))+'</li><li>'+html.escape(html.unescape(summary))+'</li><li>조건·끝 상태와 검산 근거를 직접 다시 확인해요.</li></ol>']
  text='\n'.join('<div class="layer '+('eli5' if i==0 else 'warn' if i==5 else 'formal')+'" data-explanation="'+name+'"><h4>'+heads[i]+'</h4>'+body[i]+'</div>' for i,name in enumerate(['understand','recall','start','solve','verify','pitfall','retry']))
  text+='\n<div class="sum" hidden><div class="summary-group"><h4>첫 줄</h4>'+p(html.escape(html.unescape(re.sub('<[^>]+>','',start))))+'</div><div class="summary-group"><h4>떠올릴 개념·공식</h4>'+p(summary)+'</div><div class="summary-group"><h4>검산</h4><p>본문의 조건과 독립 추적을 함께 확인해요.</p></div></div>'
  (folder/'explanations'/f"{q['id']}.html").write_text(text)
 print(v['range'],len(v['problems']),'authored')
